param([Parameter(Mandatory=$true)][string]$Path,[string]$ExpectedSourcePath='')
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$html=[IO.File]::ReadAllText($Path,[Text.Encoding]::UTF8);if($html -notmatch "connect-src\s+'none'"){throw "connect-src 'none' is missing"};$m=[regex]::Match($html,'<script id="self-extract-payload" type="application/octet-stream">(?<p>[A-Za-z0-9+/=\r\n]+)</script>','Singleline');if(-not$m.Success){throw 'Self-extract payload is missing.'};$compressed=[Convert]::FromBase64String(($m.Groups['p'].Value-replace'\s+',''));$input=[IO.MemoryStream]::new($compressed);$output=[IO.MemoryStream]::new();try{$gz=[IO.Compression.GZipStream]::new($input,[IO.Compression.CompressionMode]::Decompress);try{$gz.CopyTo($output)}finally{$gz.Dispose()};$restored=$output.ToArray()}finally{$output.Dispose();$input.Dispose()};if(-not[Text.Encoding]::UTF8.GetString($restored).TrimStart().StartsWith('<!doctype html>',[StringComparison]::OrdinalIgnoreCase)){throw 'Restored payload is not HTML.'};if($ExpectedSourcePath){$expected=[IO.File]::ReadAllBytes($ExpectedSourcePath);if($expected.Length-ne$restored.Length){throw 'Restored length mismatch.'};for($i=0;$i-lt$expected.Length;$i++){if($expected[$i]-ne$restored[$i]){throw "Restored payload differs at byte $i"}}};Write-Host "[OK] Self-extract verification passed: $Path" -ForegroundColor Green
